    realpath: str,
    snapshots: dict[frozenset[tuple[str, str]], _Snapshot],
    default_inputs: dict[str, str] | None = None,
) -> tuple[dict[str, dict[str, Any]], list[dict[str, Any]],
           dict[str, str], bytes | None, set[str]]:
